31: // The harness has no Beginners' Workshop teardown, so workshops (and the
32: // Carried Fee row, which outlives its person) stay in the disposable
33: // per-run database.
34: const memberIds: string[] = [];
35: const waitlistIds: string[] = [];
36: 
37: async function seedMember(
38: 	role: "beginners_coordinator" | "member",
