43: 		email: `bw-${lastName.toLowerCase()}-${tag}@test.com`,
44: 		roles: role === "member" ? ["member"] : [role, "member"],
45: 		firstName,
46: 		lastName,
47: 	});
48: 	memberIds.push(member.userId);
49: 	return member;
50: }
51: 
52: async function seedPerson(firstName: string, initialRegistrationDate: string) {
53: 	const person = await seedE2EScenario("waitlist", {
54: 		email: `bw-${firstName.toLowerCase()}-${tag}@example.com`,
55: 		firstName,
56: 		lastName: "Beginner",
57: 		initialRegistrationDate,
58: 	});
59: 	waitlistIds.push(person.waitlistId);
60: 	return person;
61: }
62: 
63: // An Invitation the handoff issued still names the Waitlist entry, so it
64: // goes first. None is the usual case: the journey deletes its own.
65: async function deleteInvitationOf(waitlistId: string) {
66: 	const invitation = await seedE2EScenario("beginnersWorkshopInvitation", {
67: 		waitlistId,
68: 	}).catch(() => null);
